#include <vector>
#include <complex>
#include <algorithm>
#include <cmath>
#include <omp.h>

void sortComplexByMagnitude(std::vector<std::complex<double>> &x) {
    const std::size_t n = x.size();
    if (n < 2) {
        return;
    }

    auto mag2 = [](const std::complex<double>& z) -> double {
        return std::norm(z);
    };

    // Parallel odd-even transposition sort.
    // This is correct under any thread count because, within each phase,
    // each thread only writes to disjoint element pairs.
    for (std::size_t phase = 0; phase < n; ++phase) {
        const std::size_t start = phase % 2;

        #pragma omp parallel for default(none) shared(x, n, start, mag2)
        for (std::ptrdiff_t i = static_cast<std::ptrdiff_t>(start);
             i < static_cast<std::ptrdiff_t>(n) - 1;
             i += 2) {
            const double left_mag2  = mag2(x[static_cast<std::size_t>(i)]);
            const double right_mag2 = mag2(x[static_cast<std::size_t>(i + 1)]);

            if (left_mag2 > right_mag2) {
                std::swap(x[static_cast<std::size_t>(i)],
                          x[static_cast<std::size_t>(i + 1)]);
            }
        }
    }
}
